S(G4,'ai-new','New chat','A calm empty state: one greeting and the composer.',()=>K.shell('ai','New chat',{title:'',actions:`${H.btn('Get a free month','sm','gift')}${H.ib('search','ghost sm','Search')}${H.ib('bell','ghost sm','Notifications')}`,body:`<div class="vstack" style="flex:1;align-items:center;justify-content:center;gap:10px;text-align:center"><span style="color:var(--fg-2)">${I('layers',34)}</span><div class="t-h1" style="font-size:28px">How’s it going, Zain?</div><div class="t-muted">Speak or type to begin — your assistant will take it from here.</div></div><div class="vstack" style="align-items:center;gap:10px">${tray()}<span class="t-small">Lumen may make mistakes, so double-check important info.</span></div>`}),'chat-composer,empty-state');
